begin;
with j as (select * from jsonb_to_recordset($law7d0029$[{"code_id":"GK_RF","article_number":"67.3","version_date":"1994-11-30","article_text":"1. Хозяйственное общество признается дочерним, если другое (основное) хозяйственное товарищество или общество в силу преобладающего участия в его уставном капитале, либо в соответствии с заключенным между ними договором, либо иным образом имеет возможность определять решения, принимаемые таким обществом.\n\n2. Дочернее общество не отвечает по долгам основного хозяйственного товарищества или общества.\n\nОсновное хозяйственное товарищество или общество отвечает солидарно с дочерним обществом по сделкам, заключенным последним во исполнение указаний или с согласия основного хозяйственного товарищества или общества (пункт 3 статьи 401), за исключением случаев голосования основного хозяйственного товарищества или общества по вопросу об одобрении сделки на общем собрании участников дочернего общества, а также одобрения сделки органом управления основного хозяйственного общества, если необходимость такого одобрения предусмотрена уставом дочернего и (или) основного общества. (В редакции Федерального закона от 29.06.2015 № 210-ФЗ)\n\nВ случае несостоятельности (банкротства) дочернего общества по вине основного хозяйственного товарищества или общества последнее несет субсидиарную ответственность по его долгам.\n\n3. Участники (акционеры) дочернего общества вправе требовать возмещения основным хозяйственным товариществом или обществом убытков, причиненных его действиями или бездействием дочернему обществу (статья 1064).\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 67.3. Дочернее хозяйственное общество","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"28796cacb1b8443e5c4e55f46b290f0fda7692649d7b7c3dc53078422e6ba50b"},{"code_id":"GK_RF","article_number":"69","version_date":"1994-11-30","article_text":"1. Полным признается товарищество, участники которого (полные товарищи) в соответствии с заключенным между ними договором занимаются предпринимательской деятельностью от имени товарищества и несут ответственность по его обязательствам принадлежащим им имуществом.\n\n2. Лицо может быть участником только одного полного товарищества.\n\n3. Фирменное наименование полного товарищества должно содержать либо имена (наименования) всех его участников и слова \"полное товарищество\", либо имя (наименование) одного или нескольких участников с добавлением слов \"и компания\" и слова \"полное товарищество\".","article_title":"Статья 69. Основные положения о полном товариществе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a0de696d748c176bf1774cbafe67775575113025ed09d60b902630bdf35f0ead"},{"code_id":"GK_RF","article_number":"7","version_date":"1994-11-30","article_text":"1. Общепризнанные принципы и нормы международного права и международные договоры Российской Федерации являются в соответствии с Конституцией Российской Федерации составной частью правовой системы Российской Федерации.\n\n2. Международные договоры Российской Федерации применяются к отношениям, указанным в пунктах 1 и 2 статьи 2 настоящего Кодекса, непосредственно, кроме случаев, когда из международного договора следует, что для его применения требуется издание внутригосударственного акта.\n\nЕсли международным договором Российской Федерации установлены иные правила, чем те, которые предусмотрены гражданским законодательством, применяются правила международного договора. Не допускается применение правил международных договоров Российской Федерации в их истолковании, противоречащем Конституции Российской Федерации. Такое противоречие может быть установлено в порядке, определенном федеральным конституционным законом. (В редакции Федерального закона от 08.12.2020 № 427-ФЗ)","article_title":"Статья 7. Гражданское законодательство и нормы международного права","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"25d76a0688a20077bfd968dbc56943366529abffea543a14beb3c52926b0d8e1"},{"code_id":"GK_RF","article_number":"70","version_date":"1994-11-30","article_text":"1. Полное товарищество создается и действует на основании учредительного договора. Учредительный договор подписывается всеми его участниками.\n\n2. Учредительный договор полного товарищества должен содержать помимо сведений, указанных в пункте 2 статьи 52 настоящего Кодекса, условия о размере и составе складочного капитала товарищества; о размере и порядке изменения долей каждого из участников в складочном капитале; о размере, составе, сроках и порядке внесения ими вкладов; об ответственности участников за нарушение обязанностей по внесению вкладов.","article_title":"Статья 70. Учредительный договор полного товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ccf53169b3efe82d5dbf430afc184b1a0a1bcf8f4e3e9a1faccd5da3e9b827b7"},{"code_id":"GK_RF","article_number":"71","version_date":"1994-11-30","article_text":"1. Управление деятельностью полного товарищества осуществляется по общему согласию всех участников. Учредительным договором товарищества могут быть предусмотрены случаи, когда решение принимается большинством голосов участников.\n\n2. Каждый участник полного товарищества имеет один голос, если учредительным договором не предусмотрен иной порядок определения количества голосов его участников.","article_title":"Статья 71. Управление в полном товариществе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bbe292879a7b7faaacc008f4f815d64a057e0e081047e1433292ac724beecef9"},{"code_id":"GK_RF","article_number":"72","version_date":"1994-11-30","article_text":"1. Каждый участник полного товарищества вправе действовать от имени товарищества, если учредительным договором не установлено, что все его участники ведут дела совместно, либо ведение дел поручено отдельным участникам.\n\nПри совместном ведении дел товарищества его участниками для совершения каждой сделки требуется согласие всех участников товарищества.\n\nЕсли ведение дел товарищества поручается его участниками одному или некоторым из них, остальные участники для совершения сделок от имени товарищества должны иметь доверенность от участника (участников), на которого возложено ведение дел товарищества.\n\nВ отношениях с третьими лицами товарищество не вправе ссылаться на положения учредительного договора, ограничивающие полномочия участников товарищества, за исключением случаев, когда товарищество докажет, что третье лицо в момент совершения сделки знало или заведомо должно было знать об отсутствии у участника товарищества права действовать от имени товарищества.\n\n2. Полномочия на ведение дел товарищества, предоставленные одному или нескольким участникам, могут быть прекращены судом по требованию одного или нескольких других участников товарищества при наличии к тому серьезных оснований, в частности вследствие грубого нарушения уполномоченным лицом (лицами) своих обязанностей или обнаружившейся неспособности его к разумному ведению дел. На основании судебного решения в учредительный договор товарищества вносятся необходимые изменения.","article_title":"Статья 72. Ведение дел полного товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6b23b508d634a3882d88bd92487a984908f71961c10fdf760bf4a94727a9aafb"},{"code_id":"GK_RF","article_number":"73","version_date":"1994-11-30","article_text":"1. Участник полного товарищества обязан участвовать в его деятельности в соответствии с условиями учредительного договора.\n\nПри нарушении этого правила товарищество вправе по своему выбору потребовать от такого участника возмещения причиненных товариществу убытков либо передачи товариществу всей приобретенной по таким сделкам выгоды.","article_title":"Статья 73. Обязанности участника полного товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ba90a1c356e38afdf7248b91a1c5de380a555f6a95205582bb3f77ff9200e06e"},{"code_id":"GK_RF","article_number":"74","version_date":"1994-11-30","article_text":"1. Прибыль и убытки полного товарищества распределяются между его участниками пропорционально их долям в складочном капитале, если иное не предусмотрено учредительным договором или иным соглашением участников. Не допускается соглашение об устранении кого-либо из участников товарищества от участия в прибыли или в убытках.\n\n2. Если вследствие понесенных товариществом убытков стоимость его чистых активов станет меньше размера его складочного капитала, полученная товариществом прибыль не распределяется между участниками до тех пор, пока стоимость чистых активов не превысит размер складочного капитала.","article_title":"Статья 74. Распределение прибыли и убытков полного товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"613e63fda374f829e4b0dcfe55253bce8b96cec149e2d7dcc63c9b8d3e83168e"},{"code_id":"GK_RF","article_number":"75","version_date":"1994-11-30","article_text":"1. Участники полного товарищества солидарно несут субсидиарную ответственность своим имуществом по обязательствам товарищества.\n\n2. Участник полного товарищества, не являющийся его учредителем, отвечает наравне с другими участниками по обязательствам, возникшим до его вступления в товарищество.\n\nУчастник, выбывший из товарищества, отвечает по обязательствам товарищества, возникшим до момента его выбытия, наравне с оставшимися участниками в течение двух лет со дня утверждения отчета о деятельности товарищества за год, в котором он выбыл из товарищества.\n\n3. Соглашение участников товарищества об ограничении или устранении ответственности, предусмотренной в настоящей статье, ничтожно.","article_title":"Статья 75. Ответственность участников полного товарищества по его обязательствам","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6634f8dea5d06bdbf837aee4f3a2ec47abcaf5e01dcb219c1621f81adc7b0765"},{"code_id":"GK_RF","article_number":"76","version_date":"1994-11-30","article_text":"1. В случаях выхода или смерти кого-либо из участников полного товарищества, признания одного из них безвестно отсутствующим, недееспособным, или ограниченно дееспособным, либо несостоятельным (банкротом), открытия в отношении одного из участников реорганизационных процедур по решению суда, ликвидации участвующего в товариществе юридического лица либо обращения кредитором одного из участников взыскания на часть имущества, соответствующую его доле в складочном капитале, товарищество может продолжить свою деятельность, если это предусмотрено учредительным договором товарищества или соглашением остающихся участников.\n\n2. Участники полного товарищества вправе требовать в судебном порядке исключения кого-либо из участников из товарищества по единогласному решению остающихся участников и при наличии к тому серьезных оснований, в частности вследствие грубого нарушения этим участником своих обязанностей или обнаружившейся неспособности его к разумному ведению дел.","article_title":"Статья 76. Изменение состава участников полного товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"edd539de5adc3cd8aa325ec3a4a0db2a22666583dffefdb8f919b8b0420cbc84"},{"code_id":"GK_RF","article_number":"77","version_date":"1994-11-30","article_text":"1. Участник полного товарищества вправе выйти из него, заявив об отказе от участия в товариществе.\n\nОтказ от участия в полном товариществе, учрежденном без указания срока, должен быть заявлен участником не менее чем за шесть месяцев до фактического выхода из товарищества. Досрочный отказ от участия в полном товариществе, учрежденном на определенный срок, допускается лишь по уважительной причине.\n\n2. Соглашение между участниками товарищества об отказе от права выйти из товарищества ничтожно.","article_title":"Статья 77. Выход участника из полного товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ac6aa31c5a356d9a6a7d75549b7d14130dc0311412f9d4410d4a7624a95588b5"},{"code_id":"GK_RF","article_number":"78","version_date":"1994-11-30","article_text":"1. Участнику, выбывшему из полного товарищества, выплачивается стоимость части имущества товарищества, соответствующей доле этого участника в складочном капитале, если иное не предусмотрено учредительным договором. По соглашению выбывающего участника с остающимися участниками выплата стоимости имущества может быть заменена выдачей имущества в натуре.\n\nПричитающаяся выбывающему участнику часть имущества товарищества или ее стоимость определяется по балансу, составляемому, за исключением случая, предусмотренного в статье 80 настоящего Кодекса, на момент его выбытия.\n\n2. В случае смерти участника полного товарищества его наследник может вступить в полное товарищество лишь с согласия других участников.\n\nЮридическое лицо, являющееся правопреемником участвовавшего в полном товариществе реорганизованного юридического лица, вправе вступить в товарищество с согласия других его участников, если иное не предусмотрено учредительным договором товарищества.\n\nРасчеты с наследником (правопреемником), не вступившим в товарищество, производятся в соответствии с пунктом 1 настоящей статьи. Наследник (правопреемник) участника полного товарищества несет ответственность по обязат\n\nельствам товарищества перед третьими лицами, по которым в соответствии с пунктом 2 статьи 75 настоящего Кодекса отвечал бы выбывший участник, в пределах перешедшего к нему имущества выбывшего участника товарищества.\n\n3. Если один из участников выбыл из товарищества, доли оставшихся участников в складочном капитале товарищества соответственно увеличиваются, если иное не предусмотрено учредительным договором или иным соглашением участников.","article_title":"Статья 78. Последствия выбытия участника из полного товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8d18db6e7d8cc2610de401447610f771b1599707c8ff7961b60c3938f545a8dc"},{"code_id":"GK_RF","article_number":"79","version_date":"1994-11-30","article_text":"Участник полного товарищества вправе с согласия остальных его участников передать свою долю в складочном капитале или ее часть другому участнику товарищества либо третьему лицу.\n\nПри передаче доли (части доли) иному лицу к нему переходят полностью или в соответствующей части права, принадлежавшие участнику, передавшему долю (часть доли). Лицо, которому передана доля (часть доли), несет ответственность по обязательствам товарищества в порядке, установленном абзацем первым пункта 2 статьи 75 настоящего Кодекса.\n\nПередача всей доли иному лицу участником товарищества прекращает его участие в товариществе и влечет последствия, предусмотренные пунктом 2 статьи 75 настоящего Кодекса.","article_title":"Статья 79. Передача доли участника в складочном капитале полного товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b999a03d3b0a9ee02be3d171575f19b832e477720704c91b613b1385b2bb1772"},{"code_id":"GK_RF","article_number":"8","version_date":"1994-11-30","article_text":"1. Гражданские права и обязанности возникают из оснований, предусмотренных законом и иными правовыми актами, а также из действий граждан и юридических лиц, которые хотя и не предусмотрены законом или такими актами, но в силу общих начал и смысла гражданского законодательства порождают гражданские права и обязанности.\n\nВ соответствии с этим гражданские права и обязанности возникают:\n\n1) из договоров и иных сделок, предусмотренных законом, а также из договоров и иных сделок, хотя и не предусмотренных законом, но не противоречащих ему;\n\n11) из решений собраний в случаях, предусмотренных законом; (Дополнение подпунктом - Федеральный закон от 30.12.2012 № 302-ФЗ)\n\n2) из актов государственных органов и органов местного самоуправления, которые предусмотрены законом в качестве основания возникновения гражданских прав и обязанностей;\n\n3) из судебного решения, установившего гражданские права и обязанности;\n\n4) в результате приобретения имущества по основаниям, допускаемым законом;\n\n5) в результате создания произведений науки, литературы, искусства, изобретений и иных результатов интеллектуальной деятельности;\n\n6) вследствие причинения вреда другому лицу;\n\n7) вследствие неосновательного обогащения;\n\n8) вследствие иных действий граждан и юридических лиц;\n\n9) вследствие событий, с которыми закон или иной правовой акт связывает наступление гражданско-правовых последствий.","article_title":"Статья 8. Основания возникновения гражданских прав и обязанностей","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"24e1d8ceb81040364a2f8a581c015679ae91250671f008911cae3ede88d2fff1"},{"code_id":"GK_RF","article_number":"80","version_date":"1994-11-30","article_text":"Обращение взыскания на долю участника в складочном капитале полного товарищества по собственным долгам участника допускается лишь при недостатке иного его имущества для покрытия долгов. Кредиторы такого участника вправе потребовать от полного товарищества выдела части имущества товарищества, соответствующей доле должника в складочном капитале, с целью обращения взыскания на это имущество. Подлежащая выделу часть имущества товарищества или его стоимость определяется по балансу, составленному на момент предъявления кредиторами требования о выделе.\n\nОбращение взыскания на имущество, соответствующее доле участника в складочном капитале полного товарищества, прекращает его участие в товариществе и влечет последствия, предусмотренные абзацем вторым пункта 2 статьи 75 настоящего Кодекса.","article_title":"Статья 80. Обращение взыскания на долю участника в складочном капитале полного товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eeec8e0962eb561b64ab6da14c80ed7c396d9bde2a93e4445f6ec3447dcbc2e7"},{"code_id":"GK_RF","article_number":"8.1","version_date":"1994-11-30","article_text":"1. В случаях, предусмотренных законом, права, закрепляющие принадлежность объекта гражданских прав определенному лицу, ограничения таких прав и обременения имущества (права на имущество) подлежат государственной регистрации.\n\nГосударственная регистрация прав на имущество осуществляется уполномоченным в соответствии с законом органом на основе принципов проверки законности оснований регистрации, публичности и достоверности государственного реестра.\n\nВ государственном реестре должны быть указаны данные, позволяющие определенно установить объект, на который устанавливается право, управомоченное лицо, содержание права, основание его возникновения.\n\n2. Права на имущество, подлежащие государственной регистрации, возникают, изменяются и прекращаются с момента внесения соответствующей записи в государственный реестр, если иное не установлено законом.\n\n3. В случаях, предусмотренных законом или соглашением сторон, сделка, влекущая возникновение, изменение или прекращение прав на имущество, которые подлежат государственной регистрации, должна быть нотариально удостоверена.\n\nЗапись в государственный реестр вносится при наличии заявлений об этом всех лиц, совершивших сделку, если иное не установлено законом. Если сделка совершена в нотариальной форме, запись в государственный реестр может быть внесена по заявлению любой стороны сделки, в том числе через нотариуса.\n\n4. Если право на имущество возникает, изменяется или прекращается вследствие наступления обстоятельств, указанных в законе, запись о возникновении, об изменении или о прекращении этого права вносится в государственный реестр по заявлению лица, для которого наступают такие правовые последствия. Законом может быть предусмотрено также право иных лиц обращаться с заявлением о внесении соответствующей записи в государственный реестр.\n\nЕсли право на имущество возникает, изменяется или прекращается на основании нотариально удостоверенной сделки, уполномоченный в соответствии с законом орган вправе проверить законность соответствующей сделки в случаях и в порядке, которые предусмотрены законом.\n\nПри возникновении спора в отношении зарегистрированного права лицо, которое знало или должно было знать о недостоверности данных государственного реестра, не вправе ссылаться на соответствующие данные.\n\nПриобретатель недвижимого имущества, полагавшийся при его приобретении на данные государственного реестра, признается добросовестным (статьи 234 и 302), пока в судебном порядке не доказано, что он знал или должен был знать об отсутствии права на отчуждение этого имущества у лица, от которого ему перешли права на него. (Дополнение абзацем - Федеральный закон от 16.12.2019 № 430-ФЗ)\n\nЕсли в течение трех месяцев со дня внесения в государственный реестр отметки о возражении в отношении зарегистрированного права лицо, по заявлению которого она внесена, не оспорило зарегистрированное право в суде, отметка о возражении аннулируется. В этом случае повторное внес\n\nение отметки о возражении указанного лица не допускается.\n\nЛицо, оспаривающее зарегистрированное право в суде, вправе требовать внесения в государственный реестр отметки о наличии судебного спора в отношении этого права.\n\n(Дополнение статьей - Федеральный закон от 30.12.2012 № 302-ФЗ)","article_title":"Статья 8.1. Государственная регистрация прав на имущество","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a3bb8bb9e1f7f08ad24566669c760918b821d5a71999b04ba998277579a7651d"},{"code_id":"GK_RF","article_number":"81","version_date":"1994-11-30","article_text":"Полное товарищество ликвидируется по основаниям, указанным в статье 61 настоящего Кодекса, а также в случае, когда в товариществе остается единственный участник. Такой участник вправе в течение шести месяцев с момента, когда он стал единственным участником товарищества, преобразовать такое товарищество в хозяйственное общество в порядке, установленном настоящим Кодексом.\n\nПолное товарищество ликвидируется также в случаях, указанных в пункте 1 статьи 76 настоящего Кодекса, если учредительным договором товарищества или соглашением остающихся участников не предусмотрено, что товарищество продолжит свою деятельность.","article_title":"Статья 81. Ликвидация полного товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fcd5bf2423556fdf9ffe62ff40bee0ee9362004305e85b589d851bec7fef8465"},{"code_id":"GK_RF","article_number":"82","version_date":"1994-11-30","article_text":"1. Товариществом на вере (коммандитным товариществом) признается товарищество, в котором наряду с участниками, осуществляющими от имени товарищества предпринимательскую деятельность и отвечающими по обязательствам товарищества своим имуществом (полными товарищами), имеется один или несколько участников - вкладчиков (коммандитистов), которые несут риск убытков, связанных с деятельностью товарищества, в пределах сумм внесенных ими вкладов и не принимают участия в осуществлении товариществом предпринимательской деятельности.\n\n2. Положение полных товарищей, участвующих в товариществе на вере, и их ответственность по обязательствам товарищества определяются правилами настоящего Кодекса об участниках полного товарищества.\n\n3. Лицо может быть полным товарищем только в одном товариществе на вере.\n\nУчастник полного товарищества не может быть полным товарищем в товариществе на вере.\n\nПолный товарищ в товариществе на вере не может быть участником полного товарищества.\n\nЧисло коммандитистов в товариществе на вере не должно превышать двадцать. В противном случае оно подлежит преобразованию в хозяйственное общество в течение года, а по истечении этого срока - ликвидации в судебном порядке, если число его коммандитистов не уменьшится до указанного предела. (Дополнение абзацем - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\n4. Фирменное наименование товарищества на вере должно содержать либо имена (наименования) всех полных товарищей и слова \"товарищество на вере\" или \"коммандитное товарищество\", либо имя (наименование) не менее чем одного полного товарища с добавлением слов \"и компания\" и слова \"товарищество на вере\" или \"коммандитное товарищество\".\n\nЕсли в фирменное наименование товарищества на вере включено имя вкладчика, такой вкладчик становится полным товарищем.\n\n5. К товариществу на вере применяются правила настоящего Кодекса о полном товариществе постольку, поскольку это не противоречит правилам настоящего Кодекса о товариществе на вере.","article_title":"Статья 82. Основные положения о товариществе на вере","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2ce76a04f1a656de68a90fdfedb6a0ecdbae224ca3f6ec4277928c54bc8452cf"},{"code_id":"GK_RF","article_number":"83","version_date":"1994-11-30","article_text":"1. Товарищество на вере создается и действует на основании учредительного договора. Учредительный договор подписывается всеми полными товарищами.\n\n2. Учредительный договор товарищества на вере должен содержать помимо сведений, указанных в пункте 2 статьи 52 настоящего Кодекса, условия о размере и составе складочного капитала товарищества; о размере и порядке изменения долей каждого из полных товарищей в складочном капитале; о размере, составе, сроках и порядке внесения ими вкладов, их ответственности за нарушение обязанностей по внесению вкладов; о совокупном размере вкладов, вносимых вкладчиками.","article_title":"Статья 83. Учредительный договор товарищества на вере","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2c6f3530b238e71c0dc17248817725865786dc490d87d49284c82f5be25fd148"},{"code_id":"GK_RF","article_number":"84","version_date":"1994-11-30","article_text":"1. Управление деятельностью товарищества на вере осуществляется полными товарищами. Порядок управления и ведения дел такого товарищества его полными товарищами устанавливается ими по правилам настоящего Кодекса о полном товариществе.\n\n2. Вкладчики не вправе участвовать в управлении и ведении дел товарищества на вере, выступать от его имени иначе, как по доверенности. Они не вправе оспаривать действия полных товарищей по управлению и ведению дел товарищества.","article_title":"Статья 84. Управление в товариществе на вере и ведение его дел","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d01460d17bcbc7398421f180d10844f1be5219fd78ff6f29898e1f788d3ff884"},{"code_id":"GK_RF","article_number":"85","version_date":"1994-11-30","article_text":"1. Вкладчик товарищества на вере обязан внести вклад в складочный капитал. Внесение вклада удостоверяется свидетельством об участии, выдаваемым вкладчику товариществом.\n\n2. Вкладчик товарищества на вере имеет право:\n\n1) получать часть прибыли товарищества, причитающуюся на его долю в складочном капитале, в порядке, предусмотренном учредительным договором;\n\n2) знакомиться с годовыми отчетами и балансами товарищества;\n\n3) по окончании финансового года выйти из товарищества и получить свой вклад в порядке, предусмотренном учредительным договором;\n\n4) передать свою долю в складочном капитале или ее часть другому вкладчику или третьему лицу. Вкладчики пользуются преимущественным перед третьими лицами правом покупки доли (ее части) применительно к условиям и порядку, предусмотренным пунктом 2 статьи 93 настоящего Кодекса. Передача всей доли иному лицу вкладчиком прекращает его участие в товариществе.\n\nУчредительным договором товарищества на вере могут предусматриваться и иные права вкладчика.","article_title":"Статья 85. Права и обязанности вкладчика товарищества на вере","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"39e1c0c67410bcd6a258591940ff9e31aabeb12ca8cc403525936c6ce490be53"},{"code_id":"GK_RF","article_number":"86","version_date":"1994-11-30","article_text":"1. Товарищество на вере ликвидируется при выбытии всех участвовавших в нем вкладчиков. Однако полные товарищи вправе вместо ликвидации преобразовать товарищество на вере в полное товарищество.\n\nТоварищество на вере ликвидируется также по основаниям ликвидации полного товарищества (статья 81). Однако товарищество на вере сохраняется, если в нем остаются по крайней мере один полный товарищ и один вкладчик.\n\n2. При ликвидации товарищества на вере, в том числе в случае банкротства, вкладчики имеют преимущественное перед полными товарищами право на получение вкладов из имущества товарищества, оставшегося после удовлетворения требований его кредиторов.\n\nОставшееся после этого имущество товарищества распределяется между полными товарищами и вкладчиками пропорционально их долям в складочном капитале товарищества, если иной порядок не установлен учредительным договором или соглашением полных товарищей и вкладчиков.\n\n31. Крестьянское (фермерское) хозяйство\n\n(Дополнение подпараграфом - Федеральный закон от 30.12.2012 № 302-ФЗ)","article_title":"Статья 86. Ликвидация товарищества на вере","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"18e41d6719fdadfc3b2f61aefb0d131219bb492c2d9ec7f6776f28af4b506319"},{"code_id":"GK_RF","article_number":"86.1","version_date":"1994-11-30","article_text":"1. Граждане, ведущие совместную деятельность в области сельского хозяйства без образования юридического лица на основе соглашения о создании крестьянского (фермерского) хозяйства (статья 23), вправе создать юридическое лицо - крестьянское (фермерское) хозяйство.\n\nКрестьянским (фермерским) хозяйством, создаваемым в соответствии с настоящей статьей в качестве юридического лица, признается добровольное объединение граждан на основе членства для совместной производственной или иной хозяйственной деятельности в области сельского хозяйства, основанной на их личном участии и объединении членами крестьянского (фермерского) хозяйства имущественных вкладов.\n\n2. Имущество крестьянского (фермерского) хозяйства принадлежит ему на праве собственности.\n\n3. Гражданин может быть членом только одного крестьянского (фермерского) хозяйства, созданного в качестве юридического лица.\n\n4. При обращении взыскания кредиторов крестьянского (фермерского) хозяйства на земельный участок, находящийся в собственности хозяйства, земельный участок подлежит продаже с публичных торгов в пользу лица, которое в соответствии с законом вправе продолжать использование земельного участка по целевому назначению.\n\nЧлены крестьянского (фермерского) хозяйства, созданного в качестве юридического лица, несут по обязательствам крестьянского (фермерского) хозяйства субсидиарную ответственность.\n\n5. Особенности правового положения крестьянского (фермерского) хозяйства, созданного в качестве юридического лица, определяются законом.\n\n4. Общество с ограниченной ответственностью","article_title":"Статья 86.1. Крестьянское (фермерское) хозяйство","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d5eece3b92f9db2d31a13a3b559475b4aa8874cfc912342fd4b44156ee4901a7"},{"code_id":"GK_RF","article_number":"87","version_date":"1994-11-30","article_text":"Участники общества, не полностью оплатившие доли, несут солидарную ответственность по обязательствам общества в пределах стоимости неоплаченной части доли каждого из участников.\n\n(Пункт в редакции Федерального закона от 30.12.2008 № 312-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 08.07.1999 № 138-ФЗ) (Утратил силу - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 87. Основные положения об обществе с ограниченной ответственностью","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f3a2989a980f4758cf46409de30030c0decd7d5aabba4d5b6643b6352d516674"},{"code_id":"GK_RF","article_number":"88","version_date":"1994-11-30","article_text":"Абзац. (Утратил силу - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\n(Пункт в редакции Федерального закона от 30.12.2008 № 312-ФЗ)","article_title":"Статья 88. Участники общества с ограниченной ответственностью","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2245739579907b9044981b5aed060a3b11db227f5085b5533d9c3f9c16a24f12"},{"code_id":"GK_RF","article_number":"89","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\n1. Учредители общества с ограниченной ответственностью заключают между собой договор об учреждении общества с ограниченной ответственностью, определяющий порядок осуществления ими совместной деятельности по учреждению общества, размер уставного капитала общества, размер их долей в уставном капитале общества и иные установленные законом об обществах с ограниченной ответственностью условия.\n\nДоговор об учреждении общества с ограниченной ответственностью заключается в письменной форме.\n\n2. Учредители общества с ограниченной ответственностью несут солидарную ответственность по обязательствам, связанным с его учреждением и возникшим до его государственной регистрации.\n\nОбщество с ограниченной ответственностью несет ответственность по обязательствам учредителей общества, связанным с его учреждением, только в случае последующего одобрения действий учредителей общества общим собранием участников общества. Размер ответственности общества по этим обязательствам учредителей общества может быть ограничен законом об обществах с ограниченной ответственностью.\n\n3. Учредительным документом общества с ограниченной ответственностью является его устав.\n\nУстав общества с ограниченной ответственностью должен содержать сведения о фирменном наименовании общества и месте его нахождения, размере его уставного капитала (за исключением случая, предусмотренного пунктом 2 статьи 52 настоящего Кодекса), составе и компетенции его органов, порядке принятия ими решений (в том числе решений по вопросам, принимаемым единогласно или квалифицированным большинством голосов) и иные сведения, предусмотренные законом об обществах с ограниченной ответственностью. (В редакции федеральных законов от 05.05.2014 № 99-ФЗ; от 29.06.2015 № 209-ФЗ)\n\n4. Порядок совершения иных действий по учреждению общества с ограниченной ответственностью определяется законом об обществах с ограниченной ответственностью.\n\n(Статья в редакции Федерального закона от 30.12.2008 № 312-ФЗ)","article_title":"Статья 89. Создание общества с ограниченной ответственностью и его устав","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ec8a8208cd4f0ffa2bd91a602112a0e6ad31afb10702d2edabfcf0f18626a5b6"},{"code_id":"GK_RF","article_number":"9","version_date":"1994-11-30","article_text":"1. Граждане и юридические лица по своему усмотрению осуществляют принадлежащие им гражданские права.\n\n2. Отказ граждан и юридических лиц от осуществления принадлежащих им прав не влечет прекращения этих прав, за исключением случаев, предусмотренных законом.","article_title":"Статья 9. Осуществление гражданских прав","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b6913f2fe74f3efc47ff056640e7d9ff9fc65d9747b04576a2e5479bd5eda919"},{"code_id":"GK_RF","article_number":"90","version_date":"1994-11-30","article_text":"Оплата уставного капитала общества с ограниченной ответственностью при увеличении уставного капитала путем зачета требований к обществу допускается в случаях, предусмотренных законом об обществах с ограниченной ответственностью.\n\n(Пункт в редакции Федерального закона от 27.12.2009 № 352-ФЗ)\n\nПоследствия нарушения участниками общества сроков и порядка оплаты уставного капитала общества определяются законом об обществах с ограниченной ответственностью.\n\n(Пункт в редакции Федерального закона от 05.05.2014 № 129-ФЗ)\n\nПрава и обязанности кредиторов кредитных организаций и некредитных финансовых организаций, созданных в организационно-правовой форме общества с ограниченной ответственностью, определяются также законами, регулирующими деятельность таких организаций.\n\n(Пункт в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 90. Уставный капитал общества с ограниченной ответственностью","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8928252e19fcb986bdde6336bcc419b4d3d8ec8fee15a206f64cb79310d547e0"},{"code_id":"GK_RF","article_number":"91","version_date":"1994-11-30","article_text":"(Статья утратила силу - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 91. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"96fba3f60695998f879bdbc9750258cddcd5503f2d24a982065cb51d24eabbc0"},{"code_id":"GK_RF","article_number":"92","version_date":"1994-11-30","article_text":"1. Общество с ограниченной ответственностью может быть реорганизовано или ликвидировано добровольно по единогласному решению его участников.\n\nИные основания реорганизации и ликвидации общества, а также порядок его реорганизации и ликвидации определяются настоящим Кодексом и другими законами.","article_title":"Статья 92. Реорганизация и ликвидация общества с ограниченной ответственностью","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a4e94b0f43729822f44135c7e89f8e410f96377ead7e28a26ac077376f20c94a"},{"code_id":"GK_RF","article_number":"93","version_date":"1994-11-30","article_text":"1. Переход доли или части доли участника общества в уставном капитале общества с ограниченной ответственностью к другому лицу допускается на основании сделки или в порядке правопреемства либо на ином законном основании с учетом особенностей, предусмотренных настоящим Кодексом и законом об обществах с ограниченной ответственностью.\n\n2. Продажа либо отчуждение иным образом доли или части доли в уставном капитале общества с ограниченной ответственностью третьим лицам допускается с соблюдением требований, предусмотренных законом об обществах с ограниченной ответственностью, если это не запрещено уставом общества.\n\nУчастники общества пользуются преимущественным правом покупки доли или части доли участника общества, если уставом общества не предусмотрено иное. Порядок осуществления преимущественного права и срок, в течение которого участники общества могут воспользоваться указанным правом, определяются законом об обществах с ограниченной ответственностью и уставом общества. Уставом общества также может быть предусмотрено преимущественное право покупки обществом доли или части доли участника общества, если другие участники общества не использовали свое преимущественное право покупки доли или части доли в уставном капитале общества. (В редакции  Федерального закона от 07.07.2025 № 185-ФЗ)\n\nкапитал в соответствии с пунктами 4 и 5 статьи 90 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 30.12.2008 № 312-ФЗ)","article_title":"Статья 93. Переход доли в уставном капитале общества с ограниченной ответственностью к другому лицу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"37f158dcdf8c597976b4629d102734c5055398d44fa2c53874b18c377186fdb7"},{"code_id":"GK_RF","article_number":"94","version_date":"1994-11-30","article_text":"1. Участник общества с ограниченной ответственностью вправе выйти из общества независимо от согласия других его участников или общества путем:\n\n1) подачи заявления о выходе из общества, если такая возможность предусмотрена уставом общества;\n\n2) предъявления к обществу требования о приобретении обществом доли в случаях, предусмотренных пунктом 3 статьи 93 настоящего Кодекса и законом об обществах с ограниченной ответственностью. (В редакции Федерального закона от 23.05.2018 № 116-ФЗ)\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\n(Подпараграф утратил силу - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 94. Выход участника общества с ограниченной ответственностью из общества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"327d4fc5175e4a997e437940d50e4df9dc3a6bf1f06328060801ecce7bbb5708"},{"code_id":"GK_RF","article_number":"96","version_date":"1994-11-30","article_text":"Акционеры, не полностью оплатившие акции, несут солидарную ответственность по обязательствам акционерного общества в пределах неоплаченной части стоимости принадлежащих им акций.\n\nОсобенности правового положения акционерных обществ, созданных путем приватизации государственных и муниципальных предприятий, определяются также законами и иными правовыми актами о приватизации этих предприятий.\n\nОсобенности правового положения кредитных организаций, созданных в организационно-правовой форме акционерного общества, права и обязанности их акционеров определяются также законами, регулирующими деятельность кредитных организаций. (Дополнение абзацем - Федеральный закон от 08.07.1999 № 138-ФЗ) (В редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 96. Основные положения об акционерном обществе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"483c32033b9dc939e9d4d90fecfe2fe8782bba03cbcc6b0b79426b2682b4fe64"},{"code_id":"GK_RF","article_number":"97","version_date":"1994-11-30","article_text":"1. Публичное акционерное общество (пункт 1 статьи 663) обязано представить для внесения в единый государственный реестр юридических лиц сведения о фирменном наименовании общества, содержащем указание на то, что такое общество является публичным.\n\nАкционерное общество вправе представить для внесения в единый государственный реестр юридических лиц сведения о фирменном наименовании общества, содержащем указание на то, что такое общество является публичным.\n\nАкционерное общество приобретает право публично размещать (путем открытой подписки) акции и ценные бумаги, конвертируемые в его акции, которые могут публично обращаться на условиях, установленных законами о ценных бумагах, со дня внесения в единый государственный реестр юридических лиц сведений о фирменном наименовании общества, содержащем указание на то, что такое общество является публичным.\n\n2. Приобретение непубличным акционерным обществом статуса публичного общества (пункт 1 настоящей статьи) влечет недействительность положений устава и внутренних документов общества, противоречащих правилам о публичном акционерном обществе, установленным настоящим Кодексом, законом об акционерных обществах и законами о ценных бумагах.\n\n3. В публичном акционерном обществе образуется коллегиальный орган управления общества (пункт 4 статьи 653), число членов которого не может быть менее пяти. Порядок образования и компетенция указанного коллегиального органа управления определяются законом об акционерных обществах и уставом публичного акционерного общества.\n\nУставом публичного акционерного общества не может быть отнесено к исключительной компетенции общего собрания акционеров решение вопросов, не относящихся к ней в соответствии с настоящим Кодексом и законом об акционерных обществах.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 97. Публичное акционерное общество","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b5d7952c9449261719747114920395dbe5d13651d759912ab4e7017eb004a009"},{"code_id":"GK_RF","article_number":"98","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\n1. Учредители акционерного общества заключают между собой договор, определяющий порядок осуществления ими совместной деятельности по созданию общества, размер уставного капитала общества, категории выпускаемых акций и порядок их размещения, а также иные условия, предусмотренные законом об акционерных обществах.\n\nДоговор о создании акционерного общества заключается в письменной форме путем составления одного документа, подписанного сторонами. (В редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\n2. Учредители акционерного общества несут солидарную ответственность по обязательствам, возникшим до регистрации общества.\n\nОбщество несет ответственность по обязательствам учредителей, связанным с его созданием, только в случае последующего одобрения их действий общим собранием акционеров.\n\n3. Учредительным документом акционерного общества является его устав, утвержденный учредителями.\n\nУстав акционерного общества должен содержать сведения о фирменном наименовании общества и месте его нахождения, сведения о категориях выпускаемых обществом акций, об их номинальной стоимости и количестве, о размере уставного капитала общества, правах акционеров - владельцев привилегированных акций каждого типа, составе и компетенции органов общества, а также о порядке принятия ими решений. В уставе акционерного общества также должны содержаться иные сведения, предусмотренные законом. (В редакции Федерального закона от 25.02.2022 № 20-ФЗ)\n\n4. Порядок совершения иных действий по созданию акционерного общества, в том числе компетенция учредительного собрания, определяется законом об акционерных обществах.\n\n5. Особенности создания акционерных обществ при приватизации государственных и муниципальных предприятий определяются законами и иными правовыми актами о приватизации этих предприятий.\n\n6. Акционерное общество может быть создано одним лицом или состоять из одного лица в случае приобретения одним акционером всех акций общества. Сведения об этом подлежат внесению в единый государственный реестр юридических лиц.\n\nАкционерное общество может иметь в качестве единственного участника другое хозяйственное общество, состоящее из одного лица, если иное не установлено законом. (В редакции Федерального закона  от 24.06.2025 № 178-ФЗ)\n\n(Пункт в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 98. Создание акционерного общества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4b0e78198060d7669b4f31b220d739817f862b6ab03a4b1fda31478d9871be37"},{"code_id":"GK_RF","article_number":"99","version_date":"1994-11-30","article_text":"1. Уставный капитал акционерного общества составляется из номинальной стоимости акций общества, приобретенных акционерами.\n\nАбзац. (Утратил силу - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\n2. Не допускается освобождение акционера от обязанности оплаты акций общества.\n\nОплата размещаемых обществом дополнительных акций путем зачета требований к обществу допускается в случаях, предусмотренных законом об акционерных обществах.\n\n(Пункт в редакции Федерального закона от 27.12.2009 № 352-ФЗ)\n\n3. Открытая подписка на акции акционерного общества не допускается до полной оплаты уставного капитала. При учреждении акционерного общества все его акции должны быть распределены среди учредителей.","article_title":"Статья 99. Уставный капитал акционерного общества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ca735b954ddb961c851d99055829f770549bc38f4da5d7290090035c72828286"},{"code_id":"GK_RF_2","article_number":"1000","version_date":"1994-11-30","article_text":"Комитент обязан:\n\nпринять от комиссионера все исполненное по договору комиссии;\n\nосмотреть имущество, приобретенное для него комиссионером, и известить последнего без промедления об обнаруженных в этом имуществе недостатках;\n\nосвободить комиссионера от обязательств, принятых им на себя перед третьим лицом по исполнению комиссионного поручения.","article_title":"Статья 1000. Принятие комитентом исполненного по договору комиссии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7c0fd9d241ed8c18899f614a8b3262b2ce7cd7288fac6ee7f58ffdde98c78794"},{"code_id":"GK_RF_2","article_number":"1001","version_date":"1994-11-30","article_text":"Комитент обязан помимо уплаты комиссионного вознаграждения, а в соответствующих случаях и дополнительного вознаграждения за делькредере возместить комиссионеру израсходованные им на исполнение комиссионного поручения суммы.\n\nКомиссионер не имеет права на возмещение расходов на хранение находящегося у него имущества комитента, если в законе или договоре комиссии не установлено иное.","article_title":"Статья 1001. Возмещение расходов на исполнение комиссионного поручения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3ef00bc75b9a739a7f03036e378b6c53eb2752d885ceeee565a26d2816c65378"},{"code_id":"GK_RF_2","article_number":"1002","version_date":"1994-11-30","article_text":"Договор комиссии прекращается вследствие:\n\nотказа комитента от исполнения договора;\n\nотказа комиссионера от исполнения договора в случаях, предусмотренных законом или договором;\n\nсмерти комиссионера, признания его недееспособным, ограниченно дееспособным или безвестно отсутствующим;\n\nпризнания индивидуального предпринимателя, являющегося комиссионером, несостоятельным (банкротом).\n\nВ случае объявления комиссионера несостоятельным (банкротом) его права и обязанности по сделкам, заключенным им для комитента во исполнение указаний последнего, переходят к комитенту.","article_title":"Статья 1002. Прекращение договора комиссии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ff24948bd647a6037339dfd55c28332de07f51fd7d95ff78c8849d801f479f2c"},{"code_id":"GK_RF_2","article_number":"1003","version_date":"1994-11-30","article_text":"1. Комитент вправе в любое время отказаться от исполнения договора комиссии, отменив данное комиссионеру поручение. Комиссионер вправе требовать возмещения убытков, вызванных отменой поручения.\n\n2. В случае, когда договор комиссии заключен без указания срока его действия, комитент должен уведомить комиссионера о прекращении договора не позднее чем за тридцать дней, если более продолжительный срок уведомления не предусмотрен договором.\n\nВ этом случае комитент обязан выплатить комиссионеру вознаграждение за сделки, совершенные им до прекращения договора, а также возместить комиссионеру понесенные им до прекращения договора расходы.\n\n3. В случае отмены поручения комитент обязан в срок, установленный договором комиссии, а если такой срок не установлен, незамедлительно распорядиться своим находящимся в ведении комиссионера имуществом. Если комитент не выполнит эту обязанность, комиссионер вправе сдать имущество на хранение за счет комитента либо продать его по возможно более выгодной для комитента цене.","article_title":"Статья 1003. Отмена комиссионного поручения комитентом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cb94a0fe86ff255784e38d7fd4c3fadc548b3af1396d2bf3e0c5f35f77ee42db"},{"code_id":"GK_RF_2","article_number":"1004","version_date":"1994-11-30","article_text":"1. Комиссионер не вправе, если иное не предусмотрено договором комиссии, отказаться от его исполнения, за исключением случая, когда договор заключен без указания срока его д\n\nействия. В этом случае комиссионер должен уведомить комитента о прекращении договора не позднее чем за тридцать дней, если более продолжительный срок уведомления не предусмотрен договором.\n\nКомиссионер обязан принять меры, необходимые для обеспечения сохранности имущества комитента.\n\n2. Комитент должен распорядиться своим находящимся в ведении комиссионера имуществом в течение пятнадцати дней со дня получения уведомления об отказе комиссионера исполнить поручение, если договором комиссии не установлен иной срок. Если он не выполнит эту обязанность, комиссионер вправе сдать имущество на хранение за счет комитента либо продать его по возможно более выгодной для комитента цене.\n\n3. Если договором комиссии не предусмотрено иное, комиссионер, отказавшийся от исполнения поручения, сохраняет право на комиссионное вознаграждение за сделки, совершенные им до прекращения договора, а также на возмещение понесенных до этого момента расходов.","article_title":"Статья 1004. Отказ комиссионера от исполнения договора комиссии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b81fbb930d57c6ba1b883711682607c99d302b78d31098c7c8df352b12622922"},{"code_id":"GK_RF_2","article_number":"1005","version_date":"1994-11-30","article_text":"1. По агентскому договору одна сторона (агент) обязуется за вознаграждение совершать по поручению другой стороны (принципала) юридические и иные действия от своего имени, но за счет принципала либо от имени и за счет принципала.\n\nПо сделке, совершенной агентом с третьим лицом от своего имени и за счет принципала, приобретает права и становится обязанным агент, хотя бы принципал и был назван в сделке или вступил с третьим лицом в непосредственные отношения по исполнению сделки.\n\nПо сделке, совершенной агентом с третьим лицом от имени и за счет принципала, права и обязанности возникают непосредственно у принципала.\n\n2. В случаях, когда в агентском договоре, заключенном в письменной форме, предусмотрены общие полномочия агента на совершение сделок от имени принципала, последний в отношениях с третьими лицами не вправе ссылаться на отсутствие у агента надлежащих полномочий, если не докажет, что третье лицо знало или должно было знать об ограничении полномочий агента.\n\n3. Агентский договор может быть заключен на определенный срок или без указания срока его действия.\n\n4. Законом могут быть предусмотрены особенности отдельных видов агентского договора.","article_title":"Статья 1005. Агентский договор","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"28fb17809e2f1d8ba4481a0c8bfc3114636d9b6e13f58de63f882cced95f4c57"},{"code_id":"GK_RF_2","article_number":"1006","version_date":"1994-11-30","article_text":"Принципал обязан уплатить агенту вознаграждение в размере и в порядке, установленных в агентском договоре.\n\nЕсли в агентском договоре размер агентского вознаграждения не предусмотрен и он не может быть определен исходя из условий договора, вознаграждение подлежит уплате в размере, определяемом в соответствии с пунктом 3 статьи 424 настоящего Кодекса.\n\nПри отсутствии в договоре условий о порядке уплаты агентского вознаграждения принципал обязан уплачивать вознаграждение в течение недели с момента представления ему агентом отчета за прошедший период, если из существа договора или обычаев делового оборота не вытекает иной порядок уплаты вознаграждения.","article_title":"Статья 1006. Агентское вознаграждение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ea13fde45a950f96529db126b28ee07dfe6fb10a7493978ccdff3728623ec55d"},{"code_id":"GK_RF_2","article_number":"1007","version_date":"1994-11-30","article_text":"1. Агентским договором может быть предусмотрено обязательство принципала не заключать аналогичных агентских договоров с другими агентами, действующими на определенной в договоре территории, либо воздерживаться от осуществления на этой территории самостоятельной деятельности, аналогичной деятельности, составляющей предмет агентского договора.\n\n2. Агентским договором может быть предусмотрено обязательство агента не заключать с другими принципалами аналогичных агентских договоров, которые должны исполняться на территории, полностью или частично совпадающей с территорией, указанной в договоре.\n\n3. Условия агентского договора, в силу которых агент вправе продавать товары, выполнять работы или оказывать услуги исключительно определенной категории покупателей (заказчиков) либо исключительно покупателям (заказчикам), имеющим место нахождения или место жительства на определенной в договоре территории, являются ничтожными.","article_title":"Статья 1007. Ограничения агентским договором прав принципала и агента","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7b7c004b0670d619eff1c27666db27372086b8c1ce9a6c50c72f36c305c84c8c"},{"code_id":"GK_RF_2","article_number":"1008","version_date":"1994-11-30","article_text":"1. В ходе исполнения агентского договора агент обязан представлять принципалу отчеты в порядке и в сроки, которые предусмотрены договором. При отсутствии в договоре соответствующих условий отчеты представляются агентом по мере исполнения им договора либо по окончании действия договора.\n\n2. Если агентским договором не предусмотрено иное, к отчету агента должны быть приложены необходимые доказательства расходов, произведенных агентом за счет принципала.\n\n3. Принципал, имеющий возражения по отчету агента, должен сообщить о них агенту в течение тридцати дней со дня получения отчета, если соглашением сторон не установлен иной срок. В противном случае отчет считается принятым принципалом.","article_title":"Статья 1008. Отчеты агента","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e565959f40347450e61e1ab228025473c7e03b7145012be40fdfe39e1facf005"},{"code_id":"GK_RF_2","article_number":"1009","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено агентским договором, агент вправе в целях исполнения договора заключить субагентский договор с другим лицом, оставаясь ответственным за действия субагента перед принципалом. В агентском договоре может быть предусмотрена обязанность агента заключить субагентский договор с указанием или без указания конкретных условий такого договора.\n\n2. Субагент не вправе заключать с третьими лицами сделки от имени лица, являющегося принципалом по агентскому договору, за исключением случаев, когда в соответствии с пунктом 1 статьи 187 настоящего Кодекса субагент может действовать на основе передоверия. Порядок и последствия такого передоверия определяются по правилам, предусмотренным статьей 976 настоящего Кодекса.","article_title":"Статья 1009. Субагентский договор","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4fcbc101ecb17c1924a8ae6b80fc607c2f19cfe12fd97adb0690e58e2a74abe0"},{"code_id":"GK_RF_2","article_number":"1010","version_date":"1994-11-30","article_text":"Агентский договор прекращается вследствие:\n\nотказа одной из сторон от исполнения договора, заключенного без определения срока окончания его действия;\n\nсмерти агента, признания его недееспособным, ограниченно дееспособным или безвестно отсутствующим;\n\nпризнания индивидуального предпринимателя, являющегося агентом, несостоятельным (банкротом).","article_title":"Статья 1010. Прекращение агентского договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1230010bbbb8ef56cc5679a3f0ae5db74f1277afd3a1b2f76f97b93035c1af57"},{"code_id":"GK_RF_2","article_number":"1011","version_date":"1994-11-30","article_text":"К отношениям, вытекающим из агентского договора, соответственно применяются правила, предусмотренные главой 49 или главой 51 настоящего Кодекса, в зависимости от того, действует агент по условиям этого договора от имени принципала или от своего имени, если эти правила не противоречат положениям настоящей главы или существу агентского договора.","article_title":"Статья 1011. Применение к агентским отношениям правил о договорах поручения и комиссии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c60fe6d2e89f53a3b43a941442b0928c27df6b9cc18dbebb1cea5a5589ebd45d"},{"code_id":"GK_RF_2","article_number":"1012","version_date":"1994-11-30","article_text":"1. По договору доверительного управления имуществом одна сторона (учредитель управления) передает другой стороне (доверительному управляющему) на определенный срок имущество в доверительное управление, а другая сторона обязуется осуществлять управление этим имуществом в интересах учредителя управления или указанного им лица (выгодоприобретателя).\n\nПередача имущества в доверительное управление не влечет перехода права собственности на него к доверительному управляющему.\n\n2. Осуществляя доверительное управление имуществом, доверительный управляющий вправе совершать в отношении этого имущества в соответствии с договором доверительного управления любые юридические и фактические действия в интересах выгодоприобретателя.\n\nЗаконом или договором могут быть предусмотрены ограничения в отношении отдельных действий по доверительному управлению имуществом.\n\n3. Сделки с переданным в доверительное управление имуществом доверительный управляющий совершает от своего имени, указывая при этом, что он действует в качестве такого управляющего. Это условие считается соблюденным, если при совершении действий, не требующих письменного оформления, другая сторона информирована об их совершении доверительным управляющим в этом качестве, а в письменных документах после имени или наименования доверительного управляющего сделана пометка \"Д.У.\".\n\nПри отсутствии указания о действии доверительного управляющего в этом качестве доверительный управляющий обязывается перед третьими лицами лично и отвечает перед ними только принадлежащим ему имуществом.","article_title":"Статья 1012. Договор доверительного управления имуществом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f3e67134a24214b7ab0fb882e7d525ad79bd6f1d1aaf2726c5086d97243d57aa"},{"code_id":"GK_RF_2","article_number":"1013","version_date":"1994-11-30","article_text":"1. Объектами доверительного управления могут быть предприятия и другие имущественные комплексы, отдельные объекты, относящиеся к недвижимому имуществу, ценные бумаги, права, удостоверенные бездокументарными ценными бумагами, исключительные права и другое имущество.\n\n2. Не могут быть самостоятельным объектом доверительного управления деньги, за исключением случаев, предусмотренных законом.\n\n3. Имущество, находящееся в хозяйственном ведении или оперативном управлении, не может быть передано в доверительное управление. Передача в доверительное управление имущества, находившегося в хозяйственном ведении или оперативном управлении, возможна только после ликвидации юридического лица, в хозяйственном ведении или оперативном управлении которого имущество находилось, либо прекращения права хозяйственного ведения или оперативного управления имуществом и поступления его во владение собственника по иным предусмотренным законом основаниям.","article_title":"Статья 1013. Объект доверительного управления","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"55b53fd122ae38b687547abda017bb5d11f53a37c088fc6e9882fb1dddd89480"},{"code_id":"GK_RF_2","article_number":"1014","version_date":"1994-11-30","article_text":"Учредителем доверительного управления является собственник имущества, а в случаях, предусмотренных статьей 1026 настоящего Кодекса, другое лицо.","article_title":"Статья 1014. Учредитель управления","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cd74a7ef11f279d4747cdae6bfb8b607e6bc50421901de5066b2c3b9b7c86dc4"},{"code_id":"GK_RF_2","article_number":"1015","version_date":"1994-11-30","article_text":"1. Доверительным управляющим может быть индивидуальный предприниматель или коммерческая организация, за исключением унитарного предприятия.\n\nВ случаях, когда доверительное управление имуществом осуществляется по основаниям, предусмотренным законом, доверительным управляющим может быть гражданин, не являющийся предпринимателем, или некоммерческая организация, за исключением учреждения.\n\n2. Имущество не подлежит передаче в доверительное управление государственному органу или органу местного самоуправления.\n\n3. Доверительный управляющий не может быть выгодоприобретателем по договору доверительного управления имуществом.","article_title":"Статья 1015. Доверительный управляющий","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3a0cb998595d33955d2d14e8b6618d01d1614290f6d4bd89450e4cad78c08e0d"},{"code_id":"GK_RF_2","article_number":"1016","version_date":"1994-11-30","article_text":"1. В договоре доверительного управления имуществом должны быть указаны:\n\nсостав имущества, передаваемого в доверительное управление;\n\nнаименование юридического лица или имя гражданина, в интересах которых осуществляется управление имуществом (учредителя управления или выгодоприобретателя);\n\nразмер и форма вознаграждения управляющему, если выплата вознаграждения предусмотрена договором;\n\nсрок действия договора.\n\n2. Договор доверительного управления имуществом заключается на срок, не превышающий пяти лет. Для отдельных видов имущества, передаваемого в доверительное управление, законом могут быть установлены иные предельные сроки, на которые может быть заключен договор.\n\nПри отсутствии заявления одной из сторон о прекращении договора по окончании срока его действия он считается продленным на тот же срок и на тех же условиях, какие были предусмотрены договором.","article_title":"Статья 1016. Существенные условия договора доверительного управления имуществом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f302f51be7636ec741984020db18b9bfd9d73e79b54a7fa1e4328389a03cc6b3"},{"code_id":"GK_RF_2","article_number":"1017","version_date":"1994-11-30","article_text":"1. Договор доверительного управления имуществом должен быть заключен в письменной форме.\n\n2. Договор доверительного управления недвижимым имуществом должен быть заключен в форме, предусмотренной для договора продажи недвижимого имущества. Передача недвижимого имущества в доверительное управление подлежит государственной регистрации в том же порядке, что и переход права собственности на это имущество.\n\n3. Несоблюдение формы договора доверительного управления имуществом или требования о регистрации передачи недвижимого имущества в доверительное управление влечет недействительность договора.","article_title":"Статья 1017. Форма договора доверительного управления имуществом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f634f06ef64663dc93da605fcdc36f94d6923526d3adb4ee07e69bbf7d15cc60"},{"code_id":"GK_RF_2","article_number":"1018","version_date":"1994-11-30","article_text":"1. Имущество, переданное в доверительное управление, обособляется от другого имущества учредителя управления, а также от имущества доверительного управляющего. Это имущество отражается у доверительного управляющего на отдельном балансе, и по нему ведется самостоятельный учет. Для расчетов по деятельности, связанной с доверительным управлением, открывается отдельный банковский счет.\n\n2. Обращение взыскания по долгам учредителя управления на имущество, переданное им в доверительное управление, не допускается, за исключением несостоятельности (банкротства) этого лица. При банкротстве учредителя управления доверительное управление этим имуществом прекращается и оно включается в конкурсную массу.","article_title":"Статья 1018. Обособление имущества, находящегося в доверительном управлении","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"884fbeb4c8a9c7711fe1028fa398c918907ed10872f6f0c1982bb205d2c1038b"},{"code_id":"GK_RF_2","article_number":"1019","version_date":"1994-11-30","article_text":"1. Передача заложенного имущества в доверительное управление не лишает залогодержателя права обратить взыскание на это имущество.\n\n2. Доверительный управляющий должен быть предупрежден о том, что передаваемое ему в доверительное управление имущество обременено залогом. Если доверительный управляющий не знал и не должен был знать об обременении залогом имущества, переданного ему в доверительное управление, он вправе потребовать в суде расторжения договора доверительного управления имуществом и уплаты причитающегося ему по договору вознаграждения за один год.","article_title":"Статья 1019. Передача в доверительное управление имущества, обремененного залогом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"08ff42795c38587d3b58bd6f1a7a1751a2665930b351fec29964c1f80f489b23"},{"code_id":"GK_RF_2","article_number":"1020","version_date":"1994-11-30","article_text":"1. Доверительный управляющий осуществляет в пределах, предусмотренных законом и договором доверительного управления имуществом, правомочия собственника в отношении имущества, переданного в доверительное управление. Распоряжение недвижимым имуществом доверительный управляющий осуществляет в случаях, предусмотренных договором доверительного управления.\n\n2. Права, приобретенные доверительным управляющим в результате действий по доверительному управлению имуществом, включаются в состав переданного в доверительное управление имущества. Обязанности, возникшие в результате таких действий доверительного управляющего, исполняются за счет этого имущества.\n\n3. Для защиты прав на имущество, находящееся в доверительном управлении, доверительный управляющий вправе требовать всякого устранения нарушения его прав (статьи 301, 302, 304, 305).\n\n4. Доверительный управляющий представляет учредителю управления и выгодоприобретателю отчет о своей деятельности в сроки и в порядке, которые установлены договором доверительного управления имуществом.","article_title":"Статья 1020. Права и обязанности доверительного управляющего","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"47c5d2c09fd245608c6b46ea6dd11cda68f19cc901307ad71b588deb0925f8d3"},{"code_id":"GK_RF_2","article_number":"1021","version_date":"1994-11-30","article_text":"1. Доверительный управляющий осуществляет доверительное управление имуществом лично, кроме случаев, предусмотренных пунктом 2 настоящей статьи.\n\n2. Доверительный управляющий может поручить другому лицу совершать от имени доверительного управляющего действия, необходимые для управления имуществом, если он уполномочен на это договором доверительного управления имуществом, либо получил на это согласие учредителя в письменной форме, либо вынужден к этому в силу обстоятельств для обеспечения интересов учредителя управления или выгодоприобретателя и не имеет при этом возможности получить указания учредителя управления в разумный срок.\n\nДоверительный управляющий отвечает за действия избранного им поверенного как за свои собственные.","article_title":"Статья 1021. Передача доверительного управления имуществом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"30bb4a05aba7f6e9e34129a610f0af8135ea48a5771e17e3017b528c4a2ea8c1"}]$law7d0029$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
